-- Every distinct public.tournaments.blind_structure value in production on
-- 2026-09-20, captured read-only through fn_safe_jsonb_array so the text here
-- is the jsonb the resolver actually parses. 21 structures, 370 authored
-- levels. `tag` is the first 8 hex of md5(original blind_structure text).
--
-- These are tournament CONFIGURATION rows. No player, wallet or card data.
CREATE TABLE probe_structures(
  tag        text PRIMARY KEY,
  structure  text NOT NULL,
  n_levels   integer,
  tournaments_using integer NOT NULL
);




UPDATE probe_structures SET n_levels = jsonb_array_length(structure::jsonb);
